const trigItem = $input.first().json;
const cmd = trigItem.command || "LIST_TASKS";
const params = trigItem.parameters || {};
const userId = String(trigItem.userId || trigItem.chatId || "");
const chatId = trigItem.chatId;

// 1. Resolve task date
let taskDate = params.task_date || params.due_date || params.date;
if (!taskDate && cmd !== "DELETE_ALL_TASKS") {
  const now = new Date();
  const todayIso = new Intl.DateTimeFormat("en-CA", {
    timeZone: "Asia/Kolkata",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).format(now);
  taskDate = todayIso;
} else if (taskDate && typeof taskDate === "string" && taskDate.includes("T")) {
  taskDate = taskDate.split("T")[0];
} else if (!taskDate) {
  taskDate = "";
}

// 2. Resolve priority
let priority = "MEDIUM";
if (params.priority) {
  const p = String(params.priority).toUpperCase().trim();
  if (["HIGH", "MEDIUM", "LOW"].includes(p)) priority = p;
} else if (trigItem.text && /\b(high|medium|low)\s+priority\b/i.test(trigItem.text)) {
  const match = trigItem.text.match(/\b(high|medium|low)\s+priority\b/i);
  if (match) priority = match[1].toUpperCase();
} else if (trigItem.text && /\bpriority\s+(high|medium|low)\b/i.test(trigItem.text)) {
  const match = trigItem.text.match(/\bpriority\s+(high|medium|low)\b/i);
  if (match) priority = match[1].toUpperCase();
} else if (trigItem.text && /\bto\s+(high|medium|low)\b/i.test(trigItem.text)) {
  const match = trigItem.text.match(/\bto\s+(high|medium|low)\b/i);
  if (match) priority = match[1].toUpperCase();
}

// 3. Resolve task items
let taskList = [];
if (Array.isArray(params.tasks) && params.tasks.length > 0) {
  taskList = params.tasks.map(t => typeof t === "string" ? t : (t.content || t.task_name || "")).filter(Boolean);
} else if (typeof params.tasks === "string") {
  taskList = params.tasks.split("\n").map(t => t.trim().replace(/^[-*•0-9.)\s]+/, "")).filter(Boolean);
} else if (trigItem.text && trigItem.text.includes("\n")) {
  const lines = trigItem.text.split("\n").map(l => l.trim()).filter(Boolean);
  const taskLines = lines.filter(l => !/^(?:tasks?\s+for|daily\s+tasks?|my\s+tasks?|todo)/i.test(l));
  taskList = taskLines.map(t => t.replace(/^[-*•0-9.)\s]+/, "").trim()).filter(Boolean);
}

let singleContent = params.task_name || params.content || "";
if (!singleContent && taskList.length === 1) {
  singleContent = taskList[0];
} else if (!singleContent && trigItem.text) {
  singleContent = trigItem.text.replace(/^(?:add\s+task(?:\s+for\s+[A-Za-z0-9\s,]+)?:?|new\s+task:?|create\s+task:?|update\s+task\s+[0-9]+(?:\s+to)?:?)[:\s]*/i, "").trim();
  singleContent = singleContent.replace(/\b(?:priority\s+(?:high|medium|low)|(?:high|medium|low)\s+priority|to\s+(?:high|medium|low))\b/i, "").trim();
}

let taskId = null;
if (params.task_id || params.id) {
  const rawId = String(params.task_id || params.id).replace(/[^0-9]/g, "");
  if (rawId) taskId = parseInt(rawId, 10);
}

const confirmed = params.confirmed === true || String(params.confirmed).toLowerCase() === "true";

return [{
  json: {
    command: cmd,
    chatId,
    userId,
    taskDate,
    taskList,
    singleContent,
    priority,
    taskId,
    confirmed,
    parameters: params,
    text: trigItem.text
  }
}];

const trig = $("Extract Task Input").first().json;
const list = trig.taskList.length > 0 ? trig.taskList : [trig.singleContent].filter(Boolean);

return list.map(item => ({
  json: {
    userId: trig.userId,
    chatId: String(trig.chatId),
    taskDate: trig.taskDate,
    content: item,
    priority: trig.priority || "MEDIUM"
  }
}));

const trig = $("Extract Task Input").first().json;
const rows = $input.all().map(i => i.json).filter(i => i && i.id);
if (rows.length === 0) {
  return [{ json: { chatId: trig.chatId, text: "⚠️ Failed to save tasks." } }];
}
const lines = rows.map((r, idx) => `${idx + 1}. (ID: #${r.id}) ${r.content}`);
const text = `📋 <b>${rows.length} task(s) saved for ${trig.taskDate}:</b>\n\n${lines.join("\n")}`;
return [{ json: { chatId: trig.chatId, text } }];

const trig = $("Extract Task Input").first().json;
const taskRecords = $input.all().map(i => i.json).filter(i => i && i.id);
if (taskRecords.length === 0) {
  return [{ json: { chatId: trig.chatId, text: `📋 You have no tasks for ${trig.taskDate}.` } }];
}
const lines = taskRecords.map((t, idx) => {
  const pBadge = t.priority === "HIGH" ? " [HIGH]" : (t.priority === "LOW" ? " [LOW]" : "");
  const icon = t.status === "COMPLETED" ? "✅" : (t.priority === "HIGH" ? "🔴" : "▫️");
  return `${idx + 1}. (ID: #${t.id}) ${icon} ${t.content}${pBadge}`;
});
const text = `📋 <b>TASKS FOR ${trig.taskDate}</b>\n\n${lines.join("\n")}`;
return [{ json: { chatId: trig.chatId, text } }];

const trig = $("Extract Task Input").first().json;
const r = $input.first().json;
if (!r || !r.id) {
  return [{ json: { chatId: trig.chatId, text: "⚠️ Failed to add task." } }];
}
return [{
  json: {
    chatId: trig.chatId,
    text: `📋 <b>Task added!</b> (ID: #${r.id})\n\n<b>Date:</b> ${r.task_date}\n<b>Task:</b> ${r.content}\n<b>Priority:</b> ${r.priority || 'MEDIUM'}`,
    taskId: r.id
  }
}];

const trig = $("Extract Task Input").first().json;
const r = $input.first().json;
if (r && r.id) {
  return [{ json: { chatId: trig.chatId, text: `📋 Task #${r.id} updated: "${r.content}" (Priority: ${r.priority || 'MEDIUM'})` } }];
}
return [{ json: { chatId: trig.chatId, text: "⚠️ Task not found or doesn't belong to you." } }];

const trig = $("Extract Task Input").first().json;
const r = $input.first().json;
if (r && r.id) {
  return [{ json: { chatId: trig.chatId, text: `✅ Task #${r.id} completed! (${r.content})` } }];
}
return [{ json: { chatId: trig.chatId, text: "⚠️ Task not found or doesn't belong to you." } }];

const trig = $("Extract Task Input").first().json;
const r = $input.first().json;
if (r && r.id) {
  return [{ json: { chatId: trig.chatId, text: `🗑️ Task #${r.id} deleted.` } }];
}
return [{ json: { chatId: trig.chatId, text: "⚠️ Task not found or doesn't belong to you." } }];

const trig = $("Extract Task Input").first().json;
const count = $input.all().filter(i => i.json && i.json.id).length;
const dateText = trig.taskDate ? ` for ${trig.taskDate}` : '';
return [{ json: { chatId: trig.chatId, text: `🗑️ Deleted ${count} task(s)${dateText}. All your tasks have been cleared.` } }];

const trig = $("Extract Task Input").first().json;
const dateText = trig.taskDate ? ` for ${trig.taskDate}` : '';
return [{ json: { chatId: trig.chatId, text: `⚠️ Are you sure you want to delete all tasks${dateText}? This cannot be undone.\n\nReply with "CONFIRM DELETE ALL TASKS" to proceed.` } }];
